import{_ as a,o as e,c as l,ag as r}from"./chunks/framework.CvZZEx4j.js";const b=JSON.parse('{"title":"验证与分发","description":"","frontmatter":{},"headers":[],"relativePath":"card-author/verify.md","filePath":"card-author/verify.md","lastUpdated":null}'),i={name:"card-author/verify.md"};function d(o,t,h,n,s,u){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="验证与分发" tabindex="-1">验证与分发 <a class="header-anchor" href="#验证与分发" aria-label="Permalink to &quot;验证与分发&quot;">​</a></h1><h2 id="自测流程" tabindex="-1">自测流程 <a class="header-anchor" href="#自测流程" aria-label="Permalink to &quot;自测流程&quot;">​</a></h2><p>在分发角色卡之前，请完成以下检查：</p><h3 id="准备测试环境" tabindex="-1">准备测试环境 <a class="header-anchor" href="#准备测试环境" aria-label="Permalink to &quot;准备测试环境&quot;">​</a></h3><p>最佳做法是找一个 <strong>干净的酒馆环境</strong> 进行测试（或请朋友帮忙测试），确保没有残留的本地配置干扰结果。</p><h3 id="测试清单" tabindex="-1">测试清单 <a class="header-anchor" href="#测试清单" aria-label="Permalink to &quot;测试清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>检查项</th><th>预期结果</th></tr></thead><tbody><tr><td>1</td><td>导入角色卡 PNG</td><td>角色卡正常导入，无报错</td></tr><tr><td>2</td><td>开启插件</td><td>Galgame 覆盖层正常显示</td></tr><tr><td>3</td><td>立绘加载</td><td>从远程自动加载立绘，角色图片正常显示</td></tr><tr><td>4</td><td>背景加载</td><td>背景图从远程加载并显示</td></tr><tr><td>5</td><td>Live2D 显示</td><td>模型正确加载，位置/缩放符合预期</td></tr><tr><td>6</td><td>TTS 音色</td><td>角色使用绑定的音色说话</td></tr><tr><td>7</td><td>发送消息</td><td>AI 按 Galgame 格式输出，界面正常渲染</td></tr><tr><td>8</td><td>表情切换</td><td>立绘/Live2D 随对话表情变化</td></tr></tbody></table><h2 id="分发你的角色卡" tabindex="-1">分发你的角色卡 <a class="header-anchor" href="#分发你的角色卡" aria-label="Permalink to &quot;分发你的角色卡&quot;">​</a></h2><p>验证通过后，你可以将导出的 <strong>PNG 角色卡文件</strong> 分享给用户。</p><h3 id="用户需要什么" tabindex="-1">用户需要什么 <a class="header-anchor" href="#用户需要什么" aria-label="Permalink to &quot;用户需要什么&quot;">​</a></h3><p>用户只需要：</p><ol><li>✅ 安装 SillyTavern + 酒馆助手</li><li>✅ 安装 Galgame 界面插件脚本</li><li>✅ 导入你的角色卡 PNG</li><li>🎉 开始对话即可体验</li></ol><h3 id="分发建议" tabindex="-1">分发建议 <a class="header-anchor" href="#分发建议" aria-label="Permalink to &quot;分发建议&quot;">​</a></h3><ul><li>在角色卡说明中注明「本卡支持 Galgame 界面插件，请先安装插件获得最佳体验」</li><li>附上插件安装链接</li><li>（可选）附上本文档的链接帮助用户入门</li></ul><h2 id="常见接入问题" tabindex="-1">常见接入问题 <a class="header-anchor" href="#常见接入问题" aria-label="Permalink to &quot;常见接入问题&quot;">​</a></h2><h3 id="用户反馈资源加载失败" tabindex="-1">用户反馈资源加载失败 <a class="header-anchor" href="#用户反馈资源加载失败" aria-label="Permalink to &quot;用户反馈资源加载失败&quot;">​</a></h3><ul><li>检查 GitHub 仓库是否为 <strong>公开</strong> 仓库</li><li>检查 <code>remote_assets.json</code> 文件是否已正确上传</li><li>检查 jsDelivr CDN 是否在用户所在地区可访问</li><li>建议提供备用 CDN 地址</li></ul><h3 id="live2d-模型不显示" tabindex="-1">Live2D 模型不显示 <a class="header-anchor" href="#live2d-模型不显示" aria-label="Permalink to &quot;Live2D 模型不显示&quot;">​</a></h3><ul><li>确认模型 URL 可公开访问</li><li>检查是否存在跨域（CORS）问题</li><li>建议启用 CORS 代理选项</li></ul><h3 id="tts-没有声音" tabindex="-1">TTS 没有声音 <a class="header-anchor" href="#tts-没有声音" aria-label="Permalink to &quot;TTS 没有声音&quot;">​</a></h3><ul><li>TTS 功能依赖用户本地的 TTS 引擎</li><li>如使用 GPT-SoVITS，用户需自行搭建服务</li><li>音色绑定信息会随卡分发，但用户需要有对应的音色库</li></ul><h3 id="配置没有生效" tabindex="-1">配置没有生效 <a class="header-anchor" href="#配置没有生效" aria-label="Permalink to &quot;配置没有生效&quot;">​</a></h3><ul><li>确认导出时使用的是「导出角色卡 PNG」功能</li><li>用户可在资源管理器 → 导入 → 「从当前角色卡导入」手动触发导入</li></ul>',23)])])}const m=a(i,[["render",d]]);export{b as __pageData,m as default};
